const input = $input.first()?.json || {};
const bodyData = input.body || {};

const incomingAgent = bodyData.target_agent || input.target_agent;
let agentId = '';
let agentName = '';
let incomingIntent = '';

if (typeof incomingAgent === 'object' && incomingAgent !== null) {
  agentId = String(incomingAgent.id || '').toLowerCase().trim();
  agentName = incomingAgent.name || '';
  incomingIntent = String(incomingAgent.intent || '').toLowerCase().trim();
} else if (typeof incomingAgent === 'string') {
  agentId = incomingAgent.toLowerCase().trim();
  agentName = incomingAgent;
}

let targetAgent = agentName || input.selected_agent || bodyData.selected_agent || input.agent_name || 'Governance Agent';
let determinedIntent = incomingIntent || input.intent || bodyData.intent || agentId || 'governance_check';
let governanceRoute = input.governance_route || bodyData.governance_route || agentId || 'policy_check';

const companyId = input.company_id || bodyData.company_id || input.tenant_id || bodyData.tenant_id || 'COMP001';
const customerMsg = input.customer_message || bodyData.customer_message || input.user_query || bodyData.user_query || input.user_message || bodyData.user_message || input.message || bodyData.message || 'Web console governance validation request.';

return [{
  json: {
    ...input,
    ...bodyData,

    company_id: companyId,
    tenant_id: companyId,
    session_id: input.session_id || bodyData.session_id || 'WEB-SESS-' + Math.random().toString(36).substring(7),
    lead_id: input.lead_id || bodyData.lead_id || '',
    opportunity_id: input.opportunity_id || bodyData.opportunity_id || '',

    customer_name: input.customer_name || bodyData.customer_name || '',
    email: input.email || bodyData.email || '',
    phone: input.phone || bodyData.phone || '',

    customer_message: customerMsg,
    user_query: customerMsg,

    target_agent: incomingAgent || { id: agentId, name: agentName, intent: determinedIntent },
    target_agent_id: agentId,
    target_agent_name: agentName,
    intent: determinedIntent,
    requested_service: input.requested_service || bodyData.requested_service || agentName || '',

    appointment_date: input.appointment_date || bodyData.appointment_date || input.date || bodyData.date || input.preferred_date || bodyData.preferred_date || '',
    appointment_time: input.appointment_time || bodyData.appointment_time || input.preferred_slot || bodyData.preferred_slot || input.time_slot || bodyData.time_slot || input.preferred_time || bodyData.preferred_time || '',
    preferred_slot: input.preferred_slot || bodyData.preferred_slot || input.appointment_time || bodyData.appointment_time || '',

    business_need: input.business_need || bodyData.business_need || '',
    matched_solution: input.matched_solution || bodyData.matched_solution || '',
    budget: input.budget || bodyData.budget || bodyData.estimated_budget || '',
    scope: input.scope || bodyData.scope || '',

    next_step: input.next_step || bodyData.next_step || 'general_inquiry',
    consent_to_contact: true,

    selected_agent: targetAgent,
    governance_route: governanceRoute,
    is_valid_request: true,
    is_valid_context: true,

    governance_status: 'received',
    routing_status: 'pending',
    approval_required: false,
    human_handoff: false,

    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

const companyValid = String(input.company_id || input.tenant_id || '').trim() !== '';
const sessionValid = String(input.session_id || '').trim() !== '';
const messageValid = String(input.customer_message || input.user_query || '').trim() !== '';

const intent = String(input.intent || '').trim() || 'inquiry';
const requestedService = String(input.requested_service || '').trim() || 'General Security Assessment';
const nextStep = String(input.next_step || '').trim() || 'general_inquiry';

const validIntent = intent !== '';
const validNextStep = nextStep !== '';

const contextValid =
  companyValid &&
  sessionValid &&
  messageValid &&
  validIntent &&
  validNextStep;

return [{
  json: {
    ...input,

    company_valid: companyValid,
    session_valid: sessionValid,
    message_valid: messageValid,
    intent_valid: validIntent,
    next_step_valid: validNextStep,
    context_valid: contextValid,

    intent: intent,
    requested_service: requestedService,
    next_step: nextStep,
    consent_to_contact: input.consent_to_contact !== false,

    governance_status: contextValid
      ? 'context_validated'
      : 'context_invalid',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first()?.json || {};

const targetAgentObj = input.target_agent || {};
const userObj = input.user || {};

const targetId = String(
  input.target_agent_id || 
  targetAgentObj.id || 
  targetAgentObj.target_agent_id || 
  ''
).toLowerCase().trim();

const intent = String(
  input.intent || 
  targetAgentObj.intent || 
  input.user_query || 
  input.customer_message || 
  ''
).toLowerCase().trim();

const selectedAgent = String(
  input.selected_agent || 
  targetAgentObj.name || 
  ''
).toLowerCase().trim();

const rawRoute = String(input.governance_route || '').toLowerCase().trim();

let route = 'general_ai_agent';
let targetAgent = 'General AI Agent';

if (targetId === 'quote' || intent.includes('quote') || selectedAgent.includes('quote') || intent.includes('pricing') || intent.includes('price')) {
  route = 'quote_agent';
  targetAgent = 'Quote Agent';
} else if (targetId === 'appointment' || intent.includes('appointment') || intent.includes('booking') || intent.includes('schedule') || selectedAgent.includes('appointment')) {
  route = 'appointment_agent';
  targetAgent = 'Appointment Agent';
} else if (targetId === 'sales' || intent.includes('sales') || selectedAgent.includes('sales')) {
  route = 'sales_agent';
  targetAgent = 'Sales Agent';
} else if (targetId === 'followup' || intent.includes('followup') || selectedAgent.includes('followup') || intent.includes('follow_up')) {
  route = 'followup_agent';
  targetAgent = 'Follow-up Agent';
} else if (targetId === 'marketing' || intent.includes('marketing') || selectedAgent.includes('marketing')) {
  route = 'marketing_agent';
  targetAgent = 'Marketing Agent';
} else if (targetId === 'lead' || intent.includes('lead') || selectedAgent.includes('lead')) {
  route = 'lead_capture_agent';
  targetAgent = 'Lead Capture Agent';
} else if (targetId === 'support' || intent.includes('support') || intent.includes('help') || selectedAgent.includes('support')) {
  route = 'support_agent';
  targetAgent = 'Support Agent';
} else if (targetId === 'review' || intent.includes('review') || intent.includes('feedback') || selectedAgent.includes('feedback')) {
  route = 'feedback_agent';
  targetAgent = 'Feedback';
} else if (targetId === 'whatsapp' || intent.includes('whatsapp') || selectedAgent.includes('whatsapp') || intent.includes('critical') || intent.includes('alert')) {
  route = 'whatsapp_agent';
  targetAgent = 'WhatsApp Agent';
} else if (targetId === 'analytics' || intent.includes('analytics') || selectedAgent.includes('analytics')) {
  route = 'analytics_agent';
  targetAgent = 'Analytics';
} else if (targetId === 'intake' || targetId === 'dna' || intent.includes('dna') || intent.includes('intake') || intent.includes('steward')) {
  route = 'lead_capture_agent';
  targetAgent = 'Lead Capture Agent';
} else if (targetId === 'governance' || targetId === 'orchestration' || intent.includes('governance')) {
  route = 'general_ai_agent';
  targetAgent = 'General AI Agent';
} else {
  route = 'general_ai_agent';
  targetAgent = 'General AI Agent';
}

return [{
  json: {
    ...input,
    governance_route: route,
    selected_agent: targetAgent,
    human_handoff: false
  }
}];

const input = $input.first().json;
const route = String(input.governance_route || '').trim().toLowerCase();

let policyAllowed = true;
let approvalRequired = false;
let humanHandoff = false;
let policyReason = 'Route approved under corporate governance policy.';

const allowedRoutes = [
  'quote', 'quote_agent', 'pricing', 'quote_and_proposal',
  'appointment', 'appointment_agent', 'booking',
  'sales', 'sales_agent',
  'follow_up', 'followup', 'followup_agent',
  'marketing', 'marketing_agent',
  'lead', 'lead_capture', 'lead_capture_agent', 'intake',
  'support', 'support_agent', 'customer_support',
  'review', 'feedback', 'feedback_agent',
  'whatsapp', 'whatsapp_agent',
  'analytics', 'analytics_agent',
  'dna', 'dna_steward', 'dna_steward_agent',
  'governance', 'governance_agent', 'orchestration',
  'general_ai_agent', 'general_ai', 'opt_out'
];

if (allowedRoutes.includes(route)) {
  policyAllowed = true;
  approvalRequired = false;
  humanHandoff = false;
  policyReason = 'Route ' + route + ' is authorized under zero-trust governance.';
} else if (route === 'human_handoff') {
  policyAllowed = true;
  humanHandoff = true;
  policyReason = 'Request requires human assistance.';
} else {
  policyAllowed = true;
  approvalRequired = false;
  humanHandoff = false;
  policyReason = 'Route allowed through fallback AI assistance.';
}

return [{
  json: {
    ...input,
    policy_allowed: policyAllowed,
    approval_required: approvalRequired,
    human_handoff: humanHandoff,
    policy_reason: policyReason,
    governance_status: 'policy_checked',
    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const route = String(input.governance_route || '').trim().toLowerCase();

let selectedAgent = 'General AI Agent';
let executionReason = '';
let humanHandoff = false;

if (route === 'quote_agent' || route === 'quote') {
  selectedAgent = 'Quote Agent';
  executionReason = 'Routed to Quote Agent for proposal & pricing.';
}
else if (route === 'appointment_agent' || route === 'appointment') {
  selectedAgent = 'Appointment Agent';
  executionReason = 'Routed to Appointment Agent for scheduling.';
}
else if (route === 'sales_agent' || route === 'sales') {
  selectedAgent = 'Sales Agent';
  executionReason = 'Routed to Sales Agent for enterprise solutioning.';
}
else if (route === 'followup_agent' || route === 'followup') {
  selectedAgent = 'Follow-up Agent';
  executionReason = 'Routed to Follow-up Agent for ticket tracking.';
}
else if (route === 'marketing_agent' || route === 'marketing') {
  selectedAgent = 'Marketing Agent';
  executionReason = 'Routed to Marketing Agent for advisories.';
}
else if (route === 'lead_capture_agent' || route === 'lead' || route === 'intake') {
  selectedAgent = 'Lead Capture Agent';
  executionReason = 'Routed to Lead Capture Agent for intake.';
}
else if (route === 'support_agent' || route === 'support') {
  selectedAgent = 'Support Agent';
  executionReason = 'Routed to Support Agent for emergency triage.';
}
else if (route === 'feedback_agent' || route === 'review' || route === 'feedback') {
  selectedAgent = 'Feedback';
  executionReason = 'Routed to Review & Feedback Agent for QA ingestion.';
}
else if (route === 'whatsapp_agent' || route === 'whatsapp') {
  selectedAgent = 'WhatsApp Agent';
  executionReason = 'Routed to WhatsApp Agent for mobile incident dispatch.';
}
else if (route === 'analytics_agent' || route === 'analytics') {
  selectedAgent = 'Analytics';
  executionReason = 'Routed to Analytics & Insights Agent for SLA metrics.';
}
else {
  selectedAgent = 'General AI Agent';
  executionReason = 'Routed to General AI Agent for intelligent SecOps assistance.';
}

return [{
  json: {
    ...input,
    selected_agent: selectedAgent,
    execution_target: selectedAgent,
    execution_reason: executionReason,
    human_handoff: false,
    execution_status: 'started',
    governance_status: 'route_executed',
    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

const targetAgent = input.execution_target || input.selected_agent || 'Human Handoff';

return [{
  json: {
    ...input,

    execution_id: 'EXEC-' + String($execution.id),
    execution_started_at: new Date().toISOString(),
    execution_status: 'started',

    agent_execution_status: 'started',
    agent_execution_target: targetAgent,
    selected_agent: targetAgent,

    governance_status: 'agent_execution_started',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    approval_id: 'GOV-APP-' + $execution.id,
    approval_status: 'pending',
    approval_requested_at: new Date().toISOString(),

    execution_status: 'waiting_approval',
    governance_status: 'approval_pending',

    approval_reason:
      input.policy_reason ||
      'Governance policy requires approval before execution.',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    approval_status: 'pending',
    execution_status: 'waiting_approval',
    governance_status: 'approval_pending',

    assistant_message:
      'This request requires approval before execution.',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    permission_allowed: false,
    execution_status: 'blocked',
    governance_status: 'permission_denied',

    human_handoff: true,

    assistant_message:
      'This request cannot be executed because the required agent permission is not available.',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

const selectedAgent = 
  input.execution_target || 
  input.selected_agent || 
  'Human Handoff';

return [{
  json: {
    ...input,

    route_status: 'agent_selected',
    selected_agent: selectedAgent,
    execution_target: selectedAgent,
    routing_reason: input.execution_reason || input.permission_reason || `Routed to ${selectedAgent}.`,

    governance_status: 'agent_selected',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
let selectedAgent = input.selected_agent || 'General AI Agent';

return [{
  json: {
    ...input,
    selected_agent: selectedAgent,
    execution_target: selectedAgent,
    human_handoff: false,
    decision: 'executed',
    decision_reason: `Dispatched to ${selectedAgent}.`
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    dispatch_status: 'dispatched',
    dispatched_at: new Date().toISOString(),

    agent_execution_status: 'dispatched',
    governance_status: 'agent_dispatched',

    updated_at: new Date().toISOString()
  }
}];

const result = $input.first().json;
const governance = $('Dispatch to Agent').first().json;

const failed =
  result.error ||
  result.errorMessage ||
  result.execution_error ||
  result.execution_status === 'failed';

return [{
  json: {
    ...governance,
    ...result,

    execution_result: failed ? 'failed' : 'success',
    execution_completed_at: new Date().toISOString(),

    agent_execution_status: failed
      ? 'failed'
      : 'completed',

    execution_error: failed
      ? String(
          result.error ||
          result.errorMessage ||
          result.execution_error ||
          'Agent execution failed.'
        )
      : '',

    error_handled: failed,

    governance_status: failed
      ? 'execution_failed'
      : 'agent_execution_completed',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    execution_result: 'failed',
    agent_execution_status: 'failed',
    execution_status: 'failed',

    error_handled: true,

    governance_status: 'execution_failed',

    human_handoff: true,

    failure_reason:
      input.execution_error ||
      'Agent execution failed without a specific error message.',

    assistant_message:
      'The requested operation could not be completed automatically and requires further handling.',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    execution_status: 'completed',
    agent_execution_status: 'completed',
    governance_status: 'execution_finalized',

    final_decision: 'executed',
    final_reason:
      input.execution_reason ||
      'Agent execution completed successfully.',

    completed_at: new Date().toISOString(),

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    audit_event: 'governance_execution_completed',

    audit: {
      company_id: input.company_id || '',
      session_id: input.session_id || '',
      lead_id: input.lead_id || '',
      opportunity_id: input.opportunity_id || '',
      execution_id: input.execution_id || '',

      governance_route: input.governance_route || '',
      selected_agent: input.selected_agent || '',

      policy_allowed: input.policy_allowed === true,
      approval_required: input.approval_required === true,
      permission_allowed: input.permission_allowed === true,

      execution_result: input.execution_result || '',
      final_decision: input.final_decision || '',

      timestamp: new Date().toISOString()
    },

    governance_status: 'audit_ready',

    updated_at: new Date().toISOString()
  }
}];

const audit = $('Prepare Governance Audit').first().json;

return [{
  json: {
    ...audit,

    decision: audit.final_decision || '',

    decision_reason:
      audit.final_reason ||
      audit.execution_reason ||
      audit.policy_reason ||
      '',

    decision_status: 'recorded',

    governance_status: 'decision_recorded',

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

let response = '';

if (input.insights && typeof input.insights === 'string') {
  response = input.insights;
}
else if (input.governance_route === 'opt_out') {
  response = 'You have been unsubscribed and will no longer receive contact messages.';
}
else if (input.human_handoff === true) {
  response =
    input.output ||
    input.assistant_message ||
    'This request requires human assistance.';
}
else if (input.execution_result === 'success') {
  response =
    input.output ||
    input.assistant_message ||
    input.sub_workflow_output ||
    `Your request has been routed to ${input.selected_agent || 'the appropriate agent'}.`;
}
else if (input.execution_result === 'failed') {
  response =
    input.output ||
    input.assistant_message ||
    'The request could not be completed automatically and requires further handling.';
}
else if (input.approval_status === 'pending') {
  response =
    input.output ||
    input.assistant_message ||
    'This request is waiting for approval before execution.';
}
else {
  response =
    input.output ||
    input.assistant_message ||
    'Your request has been processed.';
}

return [{
  json: {
    ...input,
    final_response: response,
    response_status: 'ready',
    governance_status: 'response_ready',
    updated_at: new Date().toISOString()
  }
}];

const items = $input.all();
let resolvedResponse = '';

for (const item of items) {
  const json = item.json;
  const candidate = json.output || json["output "] || json.final_response || json.report || json.assistant_message || json.response;
  if (candidate && candidate !== 'Your request has been routed to Marketing Agent.') {
    resolvedResponse = candidate;
    break;
  }
}

const primaryInput = items[0]?.json || {};

if (!resolvedResponse) {
  resolvedResponse = primaryInput.final_response || primaryInput.output || primaryInput["output "] || primaryInput.report || primaryInput.assistant_message || primaryInput.response || 'Your request has been processed successfully.';
}

return [{
  json: {
    company_id: primaryInput.company_id || primaryInput.tenant_id || '',
    tenant_id: primaryInput.tenant_id || primaryInput.company_id || '',
    session_id: primaryInput.session_id || '',
    lead_id: primaryInput.lead_id || '',
    opportunity_id: primaryInput.opportunity_id || '',

    governance_route: primaryInput.governance_route || '',
    selected_agent: primaryInput.selected_agent || '',

    policy_allowed: primaryInput.policy_allowed === true,
    approval_required: primaryInput.approval_required === true,
    permission_allowed: primaryInput.permission_allowed === true,
    human_handoff: primaryInput.human_handoff === true,

    execution_id: primaryInput.execution_id || '',
    execution_status: primaryInput.execution_status || 'completed',
    execution_result: primaryInput.execution_result || 'success',

    decision: primaryInput.decision || 'executed',
    decision_reason: primaryInput.decision_reason || '',

    user_query: primaryInput.user_query || primaryInput.customer_message || '',
    target_agent: primaryInput.target_agent || primaryInput.selected_agent || '',
    intent: primaryInput.intent || 'general',

    final_response: resolvedResponse,
    assistant_message: resolvedResponse,
    response_status: primaryInput.response_status || 'ready',
    status: primaryInput.execution_status || 'completed',

    governance_status: 'completed',
    completed_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,

    governance_status: 'human_handoff',
    execution_status: 'completed',
    execution_result: 'success',

    final_decision: 'human_handoff',
    final_reason: 'Request requires human assistance.',
    human_handoff: true,

    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    governance_status: 'company_not_found',
    policy_allowed: false,
    permission_allowed: false,
    approval_required: false,
    human_handoff: true,
    execution_status: 'blocked',
    execution_result: 'failed',
    final_decision: 'rejected',
    final_reason: 'No Company DNA found for the provided company_id.',
    assistant_message: 'I could not verify the company configuration for this request. Please contact support.',
    updated_at: new Date().toISOString()
  }
}];

const item = $input.first()?.json || {};
const originalInput = $('Accept Governance Request').first().json || {};

return [{  
  json: {  
    ...originalInput, 
    ...item,          
    context_valid: item.company_id ? true : false  
  }  
}];
